This PR check the sumtype mismatch returned by match expr (fix #13750).

- Check the sumtype mismatch returned by match expr.
- Add test.

```v
type St = string
type Ru = rune
type Myt = Ru | St

fn myt_t1(b bool) Myt {
	match b {
		true { return St('TRUE') }
		false { return Ru(`F`) }
	}
}

fn myt_t2(b bool) Myt {
	return match b {
		true { St('TRUE') }
		false { `F` }
	}
}

fn main() {}

PS D:\Test\v\tt1> v run .
./tt1.v:15:11: error: return type mismatch, it should be `Myt`
   13 |     return match b {
   14 |         true { St('TRUE') }
   15 |         false { `F` }
      |                 ~~~
   16 |     }
   17 | }
```

